<section class="container py-5"><div class="d-flex justify-content-between mb-4"><div><h1 class="h2">User management</h1><p class="text-muted">Manage learner, instructor, and administrator accounts.</p></div><a href="/admin" class="btn btn-outline-secondary">Back to dashboard</a></div><div class="card"><div class="table-responsive"><table class="table table-hover mb-0 align-middle"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if (!$users): ?><tr><td colspan="5" class="text-muted">No users found.</td></tr><?php endif; ?><?php foreach ($users as $user): ?><tr><td><?= e($user['name']) ?></td><td><?= e($user['email']) ?></td><td><?= e($user['role']) ?></td><td><span class="badge text-bg-<?= $user['status'] === 'active' ? 'success' : 'secondary' ?>"><?= e($user['status']) ?></span></td><td><form method="post" action="/admin/users/status" class="m-0"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e((string) $user['id']) ?>"><button class="btn btn-sm btn-outline-warning">Toggle status</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></section>